async () => {
const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const panelOf = async (title) => {
  const trig = [...document.querySelectorAll('button')].find((b) => txt(b.innerText) === title && b.hasAttribute('aria-expanded'));
  if (!trig) return null;
  if (trig.getAttribute('aria-expanded') !== 'true') { trig.scrollIntoView({ block: 'center' }); trig.click(); await wait(800); }
  return document.getElementById(trig.getAttribute('aria-controls') || '');
};
const rowInfo = (scope) => {
  const row = scope?.querySelector('[class*=filterRow]');
  if (!row) return { row: false };
  const cs = getComputedStyle(row); const rr = row.getBoundingClientRect();
  return {
    display: cs.display, paddingRight: parseFloat(cs.paddingRight), width: Math.round(rr.width),
    filters: [...row.children].map((c) => ({ name: c.getAttribute('data-filter') ?? txt(c.innerText), left: Math.round(c.getBoundingClientRect().left - rr.left), gapToRight: Math.round(rr.right - c.getBoundingClientRect().right) })),
  };
};

const out = { cabinet: rowInfo(await panelOf('Cabinet Color')), groove: rowInfo(await panelOf('Handle Groove Color')) };
const panel = await panelOf('Cabinet Color');
const link = [...panel.querySelectorAll('a')].find((a) => txt(a.innerText) === 'View in full mode');
link?.click(); await wait(1500);
const dialog = document.querySelector('[role=dialog][aria-label="Cabinet Color"]');
out.fullMode = rowInfo(dialog);
dialog?.querySelector('button[class*=closeBtn]')?.click(); await wait(600);
await panelOf('Cabinet Color');
return out;
}

